impl<T: libmessenger::client::Transport> Client<T> {
    /// Connect to the service ([`SERVICE_NAME`]), waiting for it to register for the
    /// transport's connect bound.
    pub fn connect(transport: T) -> Result<Self, ClientError> {
        let client = Self::from_connection(libmessenger::client::Connection::new(transport, SERVICE_NAME));
        client.conn.connect().map_err(ClientError::Transport)?;
        Ok(client)
    }

    /// [`Self::connect`] with one attempt, for a caller whose service being absent has
    /// a cheap fallback.
    pub fn try_connect(transport: T) -> Result<Self, ClientError> {
        let client = Self::from_connection(libmessenger::client::Connection::new(transport, SERVICE_NAME));
        client.conn.try_connect().map_err(ClientError::Transport)?;
        Ok(client)
    }

    /// A client over an existing connection: one to a member of the interface's service
    /// family (`SERVICE_INSTANCE_PREFIX` and the instance), or a test's [`libmessenger::client::Mock`].
    pub fn from_connection(conn: libmessenger::client::Connection<T>) -> Self {
        Client { conn }
    }

    /// The connection behind this client.
    pub fn connection(&self) -> &libmessenger::client::Connection<T> {
        &self.conn
    }

    /// Snapshot the session table, oldest session first.
    ///
    /// Waits for the reply at most 1000 ms (`deadline` in the `.midl`).
    pub fn sessions(&self) -> Result<SessionsReply, ClientError> {
        self.sessions_within(libmessenger::client::Deadline::millis(METHOD_SESSIONS_DEADLINE_MS as u64))
    }

    /// [`Self::sessions`] with the caller's deadline instead of the IDL's.
    pub fn sessions_within(&self, within: libmessenger::client::Deadline) -> Result<SessionsReply, ClientError> {
        let wire_body = Vec::new();
        let wire_objects = Vec::new();
        let wire_reply = self
            .conn
            .call(INTERFACE_ID, METHOD_SESSIONS, wire_body, wire_objects, within)
            ?;
        decode_sessions_reply(&wire_reply.body).map_err(ClientError::bad_reply)
    }

    /// Log in from the graphical login screen (issue #623): authenticate
    /// `user` with `secret` and open their desktop session, the same path a
    /// built-in autologin takes. Only the login screen's own identity (the
    /// `_greeter` system uid, unlabelled) may call it; a refused password is
    /// `EACCES` after the failed-login delay, a session already open `EBUSY`.
    ///
    /// Waits for the reply at most 30000 ms (`deadline` in the `.midl`).
    pub fn login(&self, user: &str, secret: &str) -> Result<u64, ClientError> {
        self.login_within(user, secret, libmessenger::client::Deadline::millis(METHOD_LOGIN_DEADLINE_MS as u64))
    }

    /// [`Self::login`] with the caller's deadline instead of the IDL's.
    pub fn login_within(&self, user: &str, secret: &str, within: libmessenger::client::Deadline) -> Result<u64, ClientError> {
        let wire_body = encode_login_args(&LoginArgs { user: user.into(), secret: secret.into() }).map_err(ClientError::bad_request)?;
        let wire_objects = Vec::new();
        let wire_reply = self
            .conn
            .call(INTERFACE_ID, METHOD_LOGIN, wire_body, wire_objects, within)
            ?;
        let reply = decode_login_reply(&wire_reply.body).map_err(ClientError::bad_reply)?;
        Ok(reply.session)
    }

    /// End the caller's graphical session (issue #623): `init` stops every
    /// task stamped with that session, and the login screen comes back. Only
    /// a task of the active graphical session may call it (`EPERM`
    /// otherwise).
    ///
    /// Waits for the reply at most 3000 ms (`deadline` in the `.midl`).
    pub fn logout(&self) -> Result<u64, ClientError> {
        self.logout_within(libmessenger::client::Deadline::millis(METHOD_LOGOUT_DEADLINE_MS as u64))
    }

    /// [`Self::logout`] with the caller's deadline instead of the IDL's.
    pub fn logout_within(&self, within: libmessenger::client::Deadline) -> Result<u64, ClientError> {
        let wire_body = Vec::new();
        let wire_objects = Vec::new();
        let wire_reply = self
            .conn
            .call(INTERFACE_ID, METHOD_LOGOUT, wire_body, wire_objects, within)
            ?;
        let reply = decode_logout_reply(&wire_reply.body).map_err(ClientError::bad_reply)?;
        Ok(reply.session)
    }
}
